PRAGMA foreign_keys = ON;

CREATE TABLE IF NOT EXISTS organizations (id TEXT PRIMARY KEY, name TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS memberships (organization_id TEXT NOT NULL, user_id TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'member', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (organization_id, user_id), FOREIGN KEY (organization_id) REFERENCES organizations(id));
CREATE TABLE IF NOT EXISTS agents (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, name TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'active', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (organization_id) REFERENCES organizations(id));
CREATE TABLE IF NOT EXISTS guardrail_policies (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, agent_id TEXT NOT NULL UNIQUE, environments TEXT NOT NULL DEFAULT '["development","staging","production"]', require_approval INTEGER NOT NULL DEFAULT 1, blocked_patterns TEXT NOT NULL DEFAULT '["delete","drop","destroy","truncate","rm -rf"]', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (organization_id) REFERENCES organizations(id), FOREIGN KEY (agent_id) REFERENCES agents(id));
CREATE TABLE IF NOT EXISTS tools (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, name TEXT NOT NULL, description TEXT NOT NULL, input_schema TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (organization_id) REFERENCES organizations(id));
CREATE TABLE IF NOT EXISTS actions (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, actor_type TEXT NOT NULL, actor_id TEXT NOT NULL, tool_id TEXT, incident_id TEXT, action_type TEXT NOT NULL, input_json TEXT NOT NULL DEFAULT '{}', output_json TEXT NOT NULL DEFAULT '{}', status TEXT NOT NULL, guardrail_decision_json TEXT NOT NULL DEFAULT '{}', approval_state TEXT NOT NULL DEFAULT 'not_required', related_resource_type TEXT, related_resource_id TEXT, operation_id TEXT, summary TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, completed_at TEXT, FOREIGN KEY (organization_id) REFERENCES organizations(id));
CREATE TABLE IF NOT EXISTS operations (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, actor_id TEXT NOT NULL, kind TEXT NOT NULL, tool TEXT, resource_type TEXT, resource_id TEXT, request_hash TEXT, state TEXT NOT NULL DEFAULT 'submitted', lease_owner TEXT, heartbeat_at TEXT, result_json TEXT NOT NULL DEFAULT '{}', error TEXT, started_at TEXT, completed_at TEXT, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (organization_id) REFERENCES organizations(id));
CREATE TABLE IF NOT EXISTS sage_decisions (id TEXT PRIMARY KEY, operation_id TEXT NOT NULL, actor_id TEXT NOT NULL, organization_id TEXT NOT NULL, workspace_id TEXT NOT NULL, capability TEXT NOT NULL, target TEXT NOT NULL, arguments_hash TEXT, approval_reference_hash TEXT, policy_version TEXT NOT NULL, verdict TEXT NOT NULL CHECK (verdict IN ('ALLOW', 'ASK', 'DENY')), reason_code TEXT NOT NULL, reason TEXT NOT NULL, evaluated_at TEXT NOT NULL, FOREIGN KEY (organization_id) REFERENCES organizations(id));
CREATE INDEX IF NOT EXISTS sage_decisions_org_time ON sage_decisions (organization_id, evaluated_at DESC);
CREATE INDEX IF NOT EXISTS sage_decisions_operation ON sage_decisions (operation_id, evaluated_at DESC);
CREATE TABLE IF NOT EXISTS rate_limits (key TEXT PRIMARY KEY, count INTEGER NOT NULL DEFAULT 0, reset_at TEXT NOT NULL);
CREATE TRIGGER IF NOT EXISTS actions_immutable_update BEFORE UPDATE ON actions BEGIN SELECT RAISE(ABORT, 'actions are append-only'); END;
CREATE TRIGGER IF NOT EXISTS actions_immutable_delete BEFORE DELETE ON actions BEGIN SELECT RAISE(ABORT, 'actions are append-only'); END;
CREATE TABLE IF NOT EXISTS incidents (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, title TEXT NOT NULL, service TEXT NOT NULL, severity TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'open', context TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (organization_id) REFERENCES organizations(id));
CREATE TABLE IF NOT EXISTS docs (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, incident_id TEXT, title TEXT NOT NULL, body TEXT NOT NULL, rationale TEXT NOT NULL DEFAULT '', version INTEGER NOT NULL DEFAULT 1, status TEXT NOT NULL DEFAULT 'proposal', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (organization_id) REFERENCES organizations(id));
CREATE TABLE IF NOT EXISTS budgets (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, period TEXT NOT NULL, limit_amount INTEGER NOT NULL, spent_amount INTEGER NOT NULL DEFAULT 0, reserved_amount INTEGER NOT NULL DEFAULT 0, FOREIGN KEY (organization_id) REFERENCES organizations(id));
CREATE UNIQUE INDEX IF NOT EXISTS budgets_org_period ON budgets (organization_id, period);
CREATE TABLE IF NOT EXISTS budget_reservations (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, action_key TEXT NOT NULL, period TEXT NOT NULL, amount INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'reserved', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, completed_at TEXT, FOREIGN KEY (organization_id) REFERENCES organizations(id));
CREATE UNIQUE INDEX IF NOT EXISTS budget_reservations_org_action ON budget_reservations (organization_id, action_key);
CREATE TABLE IF NOT EXISTS spend_log (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, agent_id TEXT, amount INTEGER NOT NULL, reason TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (organization_id) REFERENCES organizations(id));
CREATE TABLE IF NOT EXISTS integrations (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, workspace_id TEXT, provider TEXT NOT NULL, provider_display_name TEXT, provider_category TEXT, connection_id TEXT, account_reference_safe TEXT, status TEXT NOT NULL DEFAULT 'pending', connection_health TEXT NOT NULL DEFAULT 'unknown', capability_status TEXT NOT NULL DEFAULT 'unverified', capabilities_json TEXT NOT NULL DEFAULT '[]', resource_mapping_status TEXT NOT NULL DEFAULT 'not_required', mapped_resource_count INTEGER NOT NULL DEFAULT 0, metadata TEXT NOT NULL DEFAULT '{}', last_connection_check_at TEXT, last_successful_verification_at TEXT, last_sync_at TEXT, last_sync_status TEXT, last_error TEXT, next_action TEXT NOT NULL DEFAULT 'Connect to inspect available workspace resources', revoked_at TEXT, created_by TEXT, updated_by TEXT, version INTEGER NOT NULL DEFAULT 1, provider_metadata_version TEXT NOT NULL DEFAULT '1', updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (organization_id) REFERENCES organizations(id));
CREATE TABLE IF NOT EXISTS sync_jobs (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, provider TEXT NOT NULL, operation_id TEXT, status TEXT NOT NULL DEFAULT 'queued', cursor TEXT, result_json TEXT NOT NULL DEFAULT '{}', attempts INTEGER NOT NULL DEFAULT 0, error TEXT, started_at TEXT, completed_at TEXT, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (organization_id) REFERENCES organizations(id));
CREATE TABLE IF NOT EXISTS idempotency_keys (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, operation TEXT NOT NULL, request_hash TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', response_status INTEGER, response_json TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, completed_at TEXT, FOREIGN KEY (organization_id) REFERENCES organizations(id));
CREATE UNIQUE INDEX IF NOT EXISTS idempotency_scope_key ON idempotency_keys (organization_id, operation, id);
CREATE TABLE IF NOT EXISTS bootstrap_idempotency (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, operation TEXT NOT NULL, request_hash TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', response_status INTEGER, response_json TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, completed_at TEXT);
CREATE UNIQUE INDEX IF NOT EXISTS bootstrap_idempotency_scope_key ON bootstrap_idempotency (user_id, operation, id);
CREATE TABLE IF NOT EXISTS webhook_events (id TEXT PRIMARY KEY, external_id TEXT, organization_id TEXT, connection_id TEXT, operation_id TEXT, provider TEXT NOT NULL, event_type TEXT NOT NULL, payload_hash TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'received', received_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, processed_at TEXT, FOREIGN KEY (organization_id) REFERENCES organizations(id));
DROP INDEX IF EXISTS webhook_provider_event;
CREATE UNIQUE INDEX IF NOT EXISTS webhook_org_event ON webhook_events (provider, organization_id, id);
CREATE UNIQUE INDEX IF NOT EXISTS webhook_external_event ON webhook_events (provider, external_id) WHERE external_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS webhook_connection_event ON webhook_events (provider, connection_id, received_at DESC);
CREATE TABLE IF NOT EXISTS approval_tokens (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL, organization_id TEXT, action_key TEXT NOT NULL, capability_hash TEXT, arguments_hash TEXT, incident_id TEXT, instruction TEXT, status TEXT NOT NULL DEFAULT 'pending', expires_at TEXT NOT NULL, consumed_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (organization_id) REFERENCES organizations(id));
CREATE INDEX IF NOT EXISTS approval_tokens_scope ON approval_tokens (organization_id, user_id, action_key, arguments_hash, status, expires_at);
CREATE TABLE IF NOT EXISTS canvas_shares (id TEXT PRIMARY KEY, canvas_id TEXT NOT NULL, organization_id TEXT NOT NULL, mode TEXT NOT NULL DEFAULT 'private', permissions TEXT NOT NULL DEFAULT '{}', share_link TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, expires_at TEXT, FOREIGN KEY (organization_id) REFERENCES organizations(id));
CREATE TABLE IF NOT EXISTS security_scans (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, operation_id TEXT, provider TEXT NOT NULL, project_id TEXT NOT NULL, scan_type TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'queued', severity_counts TEXT NOT NULL DEFAULT '{}', result_json TEXT NOT NULL DEFAULT '{}', error TEXT, started_at TEXT, completed_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (organization_id) REFERENCES organizations(id));
CREATE INDEX IF NOT EXISTS security_scans_org_provider ON security_scans (organization_id, provider, created_at DESC);
CREATE INDEX IF NOT EXISTS security_scans_org_status ON security_scans (organization_id, status, created_at DESC);
CREATE INDEX IF NOT EXISTS canvas_shares_org_canvas ON canvas_shares (organization_id, canvas_id, created_at DESC);
CREATE INDEX IF NOT EXISTS approval_tokens_user_status ON approval_tokens (user_id, status, expires_at);
CREATE UNIQUE INDEX IF NOT EXISTS memberships_one_org_per_user ON memberships (user_id);
CREATE INDEX IF NOT EXISTS incidents_org_created ON incidents (organization_id, created_at DESC);
CREATE INDEX IF NOT EXISTS actions_org_created ON actions (organization_id, created_at DESC);
CREATE INDEX IF NOT EXISTS actions_org_status_created ON actions (organization_id, status, created_at DESC);
CREATE INDEX IF NOT EXISTS actions_org_actor_created ON actions (organization_id, actor_id, created_at DESC);
CREATE INDEX IF NOT EXISTS actions_org_tool_created ON actions (organization_id, tool_id, created_at DESC);
CREATE INDEX IF NOT EXISTS docs_org_created ON docs (organization_id, created_at DESC);
CREATE INDEX IF NOT EXISTS docs_org_status_created ON docs (organization_id, status, created_at DESC);
CREATE INDEX IF NOT EXISTS spend_log_org_created ON spend_log (organization_id, created_at DESC);
CREATE INDEX IF NOT EXISTS budget_reservations_org_status ON budget_reservations (organization_id, status, created_at DESC);
CREATE INDEX IF NOT EXISTS integrations_org_provider ON integrations (organization_id, provider, created_at DESC);
DROP INDEX IF EXISTS integrations_provider_connection;
CREATE UNIQUE INDEX IF NOT EXISTS integrations_org_provider_connection ON integrations (organization_id, provider, connection_id) WHERE connection_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS sync_jobs_org_status_created ON sync_jobs (organization_id, status, created_at DESC);
CREATE INDEX IF NOT EXISTS sync_jobs_provider_status ON sync_jobs (provider, status, created_at DESC);
CREATE INDEX IF NOT EXISTS operations_org_created ON operations (organization_id, created_at DESC);
CREATE INDEX IF NOT EXISTS operations_org_state_updated ON operations (organization_id, state, updated_at DESC);
CREATE INDEX IF NOT EXISTS operations_lease_heartbeat ON operations (state, heartbeat_at);
CREATE INDEX IF NOT EXISTS rate_limits_reset ON rate_limits (reset_at);
CREATE INDEX IF NOT EXISTS actions_operation ON actions (operation_id);
CREATE INDEX IF NOT EXISTS sync_jobs_operation ON sync_jobs (operation_id);
CREATE INDEX IF NOT EXISTS security_scans_operation ON security_scans (operation_id);
